	internal static string Pick(string portuguese, string spanish, string english)
	{
		return Current switch
		{
			AgentLanguage.Spanish => spanish, 
			AgentLanguage.English => english, 
			_ => portuguese, 
		};
	}

	internal static void Select(AgentLanguage language)
	{
		Current = language;
		try
		{
			string directoryName = Path.GetDirectoryName(SettingsPath);
			if (!string.IsNullOrWhiteSpace(directoryName))
			{
				Directory.CreateDirectory(directoryName);
			}
			File.WriteAllText(SettingsPath, JsonSerializer.Serialize(new LanguageSettings
			{
				Language = language.ToString()
			}));
		}
		catch
		{
		}
	}

	private static AgentLanguage Load()
	{
		try
		{
			if (!File.Exists(SettingsPath))
			{
				return AgentLanguage.Portuguese;
			}
			AgentLanguage result;
			return Enum.TryParse<AgentLanguage>(JsonSerializer.Deserialize<LanguageSettings>(File.ReadAllText(SettingsPath))?.Language, ignoreCase: true, out result) ? result : AgentLanguage.Portuguese;
		}
		catch
		{
			return AgentLanguage.Portuguese;
		}
	}
}
